use super::*;
use crate::local_database::{migrate_database,write_snapshot_in_tx};
use sqlx::{sqlite::{SqliteConnectOptions,SqlitePoolOptions}};
use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH}};
fn fixture_root()->PathBuf{let p=std::env::temp_dir().join(format!("starlane-owned-delete-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&p).unwrap();p}
fn context()->Value{json!({"version":1,"serverBase":"local-vault","accountId":"local-user","sessionId":"original-local-session","cacheScope":"local-session","storageMode":"local","provider":"none"})}
async fn initialize(root:&PathBuf)->String{
 fs::create_dir(root.join(".starlane")).unwrap();let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3")).create_if_missing(true)).await.unwrap();migrate_database(&pool).await.unwrap();let mut tx=pool.begin().await.unwrap();let revision=write_snapshot_in_tx(&mut tx,"none",&json!({"spaces":[{"id":"s","name":"Original"}],"documents":[{"id":"p","space_id":"s","title":"Original","created_at":"created-original","deleted_at":"trash-original"}],"assets":[],"sync_state":{"state":"idle","updated_at":"before","queued_operations":[]}})).await.unwrap();tx.commit().await.unwrap();pool.close().await;revision
}
fn owner(root:&PathBuf,revision:&str)->native_archive_capture::Owner{let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();native_archive_capture::Owner::capture(selection,"none",revision,context()).unwrap()}
fn request(owner:&native_archive_capture::Owner)->Request{Request{operation_id:"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa".into(),queued_at:"2026-10-11T12:00:00Z".into(),space_id:"s".into(),document_id:"p".into(),original_target:Target{created_at:"created-original".into(),deleted_at:"trash-original".into()},original_binding:owner.delete_binding().unwrap()}}
#[tokio::test]
async fn exact_canonical_delete_and_restart_receipt_never_reads_stale_mirror(){
 let root=fixture_root();let revision=initialize(&root).await;fs::write(root.join("starlane-vault-none.json"),b"STALE FOREIGN JSON").unwrap();let original=owner(&root,&revision);let req=request(&original);let result=original.delete_original_trash(context(),req.clone()).await.unwrap();assert_eq!(result["canonical_committed"],true);assert_eq!(result["snapshot"]["documents"],json!([]));assert_eq!(result["snapshot"]["sync_state"]["queued_operations"][0]["id"],req.operation_id);assert_eq!(result["snapshot"]["sync_state"]["queued_operations"][0]["payload"]["original_target"]["deleted_at"],"trash-original");assert_eq!(fs::read(root.join("starlane-vault-none.json")).unwrap(),b"STALE FOREIGN JSON");let restarted=owner(&root,&revision).delete_original_trash(context(),req).await.unwrap();assert_eq!(restarted["reconciled"],true);assert_eq!(restarted["receipt"],result["receipt"]);fs::remove_dir_all(root).unwrap();
}
#[tokio::test]
async fn changed_trash_cycle_and_context_refuse_before_canonical_write(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let mut req=request(&original);req.original_target.deleted_at="foreign-cycle".into();assert!(original.delete_original_trash(context(),req).await.unwrap_err().contains("Trash cycle"));let original=owner(&root,&revision);let req=request(&original);let mut foreign=context();foreign["sessionId"]=json!("foreign");assert!(original.delete_original_trash(foreign,req).await.unwrap_err().contains("context"));let original=owner(&root,&revision);original.with_capture(context(),|c|{assert_eq!(c.snapshot["documents"][0]["id"],"p");assert_eq!(c.snapshot["sync_state"]["queued_operations"],json!([]));Ok(())}).await.unwrap();fs::remove_dir_all(root).unwrap();
}
#[tokio::test]
async fn equal_content_foreign_database_replacement_refuses_held_owner(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);let db=root.join(".starlane/starlane-notes.sqlite3");let copy=db.with_extension("foreign");fs::copy(&db,&copy).unwrap();fs::rename(copy,&db).unwrap();assert!(original.delete_original_trash(context(),req).await.unwrap_err().contains("identity"));fs::remove_dir_all(root).unwrap();
}
#[test]
#[ignore = "fresh process child invoked by parent test"]
fn restart_receipt_child(){
 let root=PathBuf::from(std::env::var("STARLANE_PRIVATE_DELETE_CHILD_ROOT").unwrap());let revision=std::env::var("STARLANE_PRIVATE_DELETE_CHILD_REVISION").unwrap();let expected=std::env::var("STARLANE_PRIVATE_DELETE_CHILD_RECEIPT_SHA").unwrap();tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap().block_on(async{let o=owner(&root,&revision);let req=request(&o);let result=o.delete_original_trash(context(),req).await.unwrap();assert_eq!(result["reconciled"],true);use sha2::{Digest,Sha256};assert_eq!(format!("{:x}",Sha256::digest(result["receipt"].as_str().unwrap().as_bytes())),expected);});
}
#[tokio::test]
async fn genuine_fresh_process_restart_reconciles_exact_original_receipt(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);let result=original.delete_original_trash(context(),req).await.unwrap();use sha2::{Digest,Sha256};let sha=format!("{:x}",Sha256::digest(result["receipt"].as_str().unwrap().as_bytes()));let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","local_database::attachment_download_owner::native_document_delete::tests::restart_receipt_child","--ignored","--nocapture"]).env("STARLANE_PRIVATE_DELETE_CHILD_ROOT",&root).env("STARLANE_PRIVATE_DELETE_CHILD_REVISION",revision).env("STARLANE_PRIVATE_DELETE_CHILD_RECEIPT_SHA",sha).output().unwrap();assert!(output.status.success(),"{} {}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));assert!(String::from_utf8_lossy(&output.stdout).contains("1 passed"));fs::remove_dir_all(root).unwrap();
}
#[tokio::test]
async fn copied_receipt_database_and_recreated_page_never_gain_retry_authority(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);original.delete_original_trash(context(),req.clone()).await.unwrap();let path=root.join(".starlane/starlane-notes.sqlite3");let copy=path.with_extension("copied");fs::copy(&path,&copy).unwrap();fs::rename(copy,&path).unwrap();assert!(owner(&root,&revision).delete_original_trash(context(),req).await.unwrap_err().contains("binding changed"));fs::remove_dir_all(root).unwrap();
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);original.delete_original_trash(context(),req.clone()).await.unwrap();let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();let mut tx=pool.begin().await.unwrap();write_snapshot_in_tx(&mut tx,"none",&json!({"spaces":[{"id":"s","name":"Original"}],"documents":[{"id":"p","space_id":"s","title":"Replacement","created_at":"replacement","deleted_at":"new-trash-cycle"}],"assets":[],"sync_state":{"state":"idle","updated_at":"before","queued_operations":[]}})).await.unwrap();tx.commit().await.unwrap();pool.close().await;assert!(owner(&root,&revision).delete_original_trash(context(),req).await.unwrap_err().contains("replacement page/database"));fs::remove_dir_all(root).unwrap();
}
#[tokio::test]
async fn waiting_native_delete_refuses_replaced_selected_root_before_open(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);let guard=snapshot_commit_lock().lock().await;
 let task=tokio::spawn(original.delete_original_trash(context(),req));tokio::task::yield_now().await;
 let retired=root.with_extension("retired-root");fs::rename(&root,&retired).unwrap();fs::create_dir(&root).unwrap();fs::create_dir(root.join(".starlane")).unwrap();fs::copy(retired.join(".starlane/starlane-notes.sqlite3"),root.join(".starlane/starlane-notes.sqlite3")).unwrap();
 drop(guard);assert!(task.await.unwrap().is_err());assert!(!root.join("starlane-vault-none.json").exists());fs::remove_dir_all(root).unwrap();fs::remove_dir_all(retired).unwrap();
}
#[tokio::test]
async fn receipt_uuid_reuse_for_different_target_and_malformed_canonical_rows_refuse(){
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);original.delete_original_trash(context(),req.clone()).await.unwrap();let mut changed=req;changed.original_target.deleted_at="foreign-cycle".into();assert!(owner(&root,&revision).delete_original_trash(context(),changed).await.unwrap_err().contains("receipt/request differs"));fs::remove_dir_all(root).unwrap();
 let root=fixture_root();let revision=initialize(&root).await;let original=owner(&root,&revision);let req=request(&original);let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();sqlx::query("UPDATE local_vault_records SET payload='malformed' WHERE collection='documents'").execute(&pool).await.unwrap();pool.close().await;assert!(original.delete_original_trash(context(),req).await.unwrap_err().contains("Malformed canonical"));fs::remove_dir_all(root).unwrap();
}
#[tokio::test]
#[ignore = "advertised genuine 100 MiB owner retained-binary acceptance"]
async fn genuine_100mib_original_owner_receipt_and_all_binary_bytes_retained_after_delete(){
 use sha2::{Digest,Sha256};use std::io::Read;
 let root=fixture_root();let _=initialize(&root).await;let length=100*1024*1024;let chunk=vec![7u8;65536];let mut hash=Sha256::new();for _ in 0..1600{hash.update(&chunk)}let sha=format!("{:x}",hash.finalize());
 let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();let origin=json!({"version":1,"serverBase":"https://fixture.invalid","accountId":"original-actor","sessionId":"original-server-session","cacheScope":"session-original","storageMode":"server","provider":"none"});
 let import=custody::Request{destination:custody::Destination::capture(&selection).unwrap(),association:custody::Association{space_id:"s".into(),document_id:"p".into()},operation_id:"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb".into(),origin:origin.clone(),server_version_raw:serde_json::to_string(&json!({"version_id":"exact-original-version","logical_attachment_id":"exact-original-family","version_number":1,"original_space_id":"s","original_document_id":"p","uploader_id":"original-actor","original_name":"same-name.bin","mime_type":"application/octet-stream","byte_length":length,"binary_sha256":sha,"original_created_at":"2026-10-11T12:00:00Z"})).unwrap()};
 let imported=custody::Captured::capture(selection,import.clone(),&origin).unwrap();imported.begin(&origin).await.unwrap();for i in 0..1600{imported.append(&origin,i,chunk.clone()).await.unwrap()}let outcome=imported.finish(&origin).await.unwrap();assert_eq!(outcome["state"],"current");let ack=outcome["original_ack"]["asset"].clone();assert!(ack.is_object());
 let path=root.join(".starlane/starlane-notes.sqlite3");let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(&path)).await.unwrap();let raw:String=sqlx::query_scalar("SELECT receipt FROM native_attachment_download_receipts WHERE operation_id=?1").bind(&import.operation_id).fetch_one(&pool).await.unwrap();let revision:String=sqlx::query_scalar("SELECT value FROM local_vault_metadata WHERE key='canonical_revision'").fetch_one(&pool).await.unwrap();pool.close().await;
 let original=owner(&root,&revision);let req=request(&original);let result=original.delete_original_trash(context(),req).await.unwrap();assert_eq!(result["snapshot"]["assets"][0],ack);
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(path)).await.unwrap();let retained:String=sqlx::query_scalar("SELECT receipt FROM native_attachment_download_receipts WHERE operation_id=?1").bind(&import.operation_id).fetch_one(&pool).await.unwrap();assert_eq!(retained.as_bytes(),raw.as_bytes());pool.close().await;
 let mut file=fs::File::open(ack["vault_path"].as_str().unwrap()).unwrap();let mut read=0;let mut buffer=[0u8;65536];let mut hash=Sha256::new();loop{let n=file.read(&mut buffer).unwrap();if n==0{break}assert!(buffer[..n].iter().all(|v|*v==7));hash.update(&buffer[..n]);read+=n;}assert_eq!(read,length);assert_eq!(format!("{:x}",hash.finalize()),sha);
 assert!(imported.delivery_snapshot(&origin).await.err().unwrap().contains("association"));fs::remove_dir_all(root).unwrap();
}
#[tokio::test(flavor="multi_thread",worker_threads=2)]
#[ignore = "actual fresh process Tauri IPC worker, not installed GUI"]
async fn native_delete_ipc_child(){
 let root=PathBuf::from(std::env::var("STARLANE_PRIVATE_DELETE_CHILD_ROOT").unwrap());let app=tauri::test::mock_builder().plugin(tauri_plugin_store::Builder::new().build()).invoke_handler(tauri::generate_handler![delete_original_native_trash_document,super::super::native_archive_context::describe_current_native_vault_archive,super::super::native_archive_context::list_original_native_trash_documents]).build(tauri::test::mock_context(tauri::test::noop_assets())).unwrap();let settings=tauri_plugin_store::resolve_store_path(app.handle(),"settings.json").unwrap();assert!(settings.starts_with(&root));fs::create_dir_all(settings.parent().unwrap()).unwrap();fs::write(&settings,json!({"vault_path":root}).to_string()).unwrap();let window=tauri::WebviewWindowBuilder::new(&app,"main",tauri::WebviewUrl::App("index.html".into())).build().unwrap();
 let call=|cmd:&str,body:Value|tauri::test::get_ipc_response(&window,tauri::webview::InvokeRequest{cmd:cmd.into(),callback:tauri::ipc::CallbackFn(0),error:tauri::ipc::CallbackFn(1),url:"http://tauri.localhost".parse().unwrap(),body:tauri::ipc::InvokeBody::Json(body),headers:Default::default(),invoke_key:tauri::test::INVOKE_KEY.into()});
 let described:Value=call("describe_current_native_vault_archive",json!({"provider":"none","context":context(),"current":context()})).unwrap().deserialize().unwrap();let trash:Value=call("list_original_native_trash_documents",json!({"provider":"none","context":context(),"current":context(),"spaceId":"s"})).unwrap().deserialize().unwrap();assert_eq!(trash["binding"]["revision"],described["binding"]["revision"]);assert!(trash["binding"]["custody"].is_object());assert_eq!(trash["documents"][0]["created_at"],"created-original");assert_eq!(trash["documents"][0]["deleted_at"],"trash-original");let revision=described["binding"]["revision"].as_str().unwrap();let o=owner(&root,revision);let req=request(&o);assert_eq!(req.original_binding,trash["binding"]);let body=json!({"provider":"none","context":context(),"current":context(),"request":req});
 if let Ok(mode)=std::env::var("STARLANE_PRIVATE_DELETE_REPLACEMENT_MODE") {
  let db=root.join(".starlane/starlane-notes.sqlite3");let before=fs::read(&db).unwrap();
  let retired=root.with_extension("selected-retired");
  if mode=="database"{let copy=db.with_extension("replacement");fs::copy(&db,&copy).unwrap();fs::rename(copy,&db).unwrap();}
  else {fn copy_tree(a:&std::path::Path,b:&std::path::Path){fs::create_dir(b).unwrap();for e in fs::read_dir(a).unwrap(){let e=e.unwrap();let d=b.join(e.file_name());if e.file_type().unwrap().is_dir(){copy_tree(&e.path(),&d)}else{fs::copy(e.path(),d).unwrap();}}}fs::rename(&root,&retired).unwrap();copy_tree(&retired,&root);}
  assert_eq!(fs::read(&db).unwrap(),before);let rejected=call("delete_original_native_trash_document",body);assert!(rejected.is_err(),"replacement cannot inherit displayed deletion authority");assert_eq!(fs::read(&db).unwrap(),before);
  if retired.exists(){fs::remove_dir_all(retired).unwrap();}println!("ACTUAL_NATIVE_DELETE_REPLACEMENT_AFTER_LIST_REFUSAL_PASS");return;
 }
 let mut foreign=body.clone();foreign["current"]["sessionId"]=json!("foreign");assert!(call("delete_original_native_trash_document",foreign).is_err());let result:Value=call("delete_original_native_trash_document",body.clone()).unwrap().deserialize().unwrap();assert_eq!(result["canonical_committed"],true);let retry:Value=call("delete_original_native_trash_document",body).unwrap().deserialize().unwrap();assert_eq!(retry["reconciled"],true);assert_eq!(retry["receipt"],result["receipt"]);println!("ACTUAL_NATIVE_DELETE_IPC_ORIGINAL_DESCRIPTOR_CONTEXT_SQL_RECEIPT_RETRY_PASS");
}
#[tokio::test]
async fn actual_native_command_ipc_current_descriptor_and_exact_retry(){
 let root=fixture_root();let _=initialize(&root).await;let mut child=std::process::Command::new(std::env::current_exe().unwrap());child.args(["--exact","local_database::attachment_download_owner::native_document_delete::tests::native_delete_ipc_child","--ignored","--nocapture"]).env("STARLANE_PRIVATE_DELETE_CHILD_ROOT",&root);for(key,name)in[("XDG_CONFIG_HOME","config"),("XDG_DATA_HOME","data"),("XDG_CACHE_HOME","cache"),("XDG_STATE_HOME","state")]{let path=root.join(name);fs::create_dir_all(&path).unwrap();child.env(key,path);}let output=child.output().unwrap();assert!(output.status.success(),"{} {}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));assert!(String::from_utf8_lossy(&output.stdout).contains("ACTUAL_NATIVE_DELETE_IPC_ORIGINAL_DESCRIPTOR_CONTEXT_SQL_RECEIPT_RETRY_PASS"));fs::remove_dir_all(root).unwrap();
}

#[tokio::test]
async fn actual_native_command_refuses_equal_content_root_and_database_replacement_after_list(){
 for mode in ["root","database"]{let root=fixture_root();let _=initialize(&root).await;let mut child=std::process::Command::new(std::env::current_exe().unwrap());child.args(["--exact","local_database::attachment_download_owner::native_document_delete::tests::native_delete_ipc_child","--ignored","--nocapture"]).env("STARLANE_PRIVATE_DELETE_CHILD_ROOT",&root).env("STARLANE_PRIVATE_DELETE_REPLACEMENT_MODE",mode);for(key,name)in[("XDG_CONFIG_HOME","config"),("XDG_DATA_HOME","data"),("XDG_CACHE_HOME","cache"),("XDG_STATE_HOME","state")]{let path=root.join(name);fs::create_dir_all(&path).unwrap();child.env(key,path);}let output=child.output().unwrap();assert!(output.status.success(),"mode={mode}: {} {}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));assert!(String::from_utf8_lossy(&output.stdout).contains("ACTUAL_NATIVE_DELETE_REPLACEMENT_AFTER_LIST_REFUSAL_PASS"));fs::remove_dir_all(root).unwrap();}
}
